+    const { warnings, yamlConfig } = convertJsonMcpConfigToYamlMcpConfig(
+      name,
+      config,
+    );
+    allWarnings.push(...warnings);
+    return yamlConfig;
+  });
+
+  return {
+    warnings: allWarnings,
